/* ── paraboloid cap  z = capFn(x,y)  over its own z ≥ 0 footprint ───────── */
let capRads = null;
function capRadius(th) {
  const cx = Math.cos(th), sy = Math.sin(th);
  if (!(okc(0, 0) > 0)) return 2;
  let lo = 0, hi = 3.4;
  for (let r = 0.04; r <= 3.4; r += 0.04) {
    const v = okc(r * cx, r * sy);
    if (!(Number.isFinite(v) && v >= 0)) { hi = r; break; }
    lo = r;
  }
  for (let k = 0; k < 18; k++) {
    const m = 0.5 * (lo + hi);
    const v = okc(m * cx, m * sy);
    if (Number.isFinite(v) && v >= 0) lo = m; else hi = m;
  }
  return Math.max(0.05, lo);
}

function buildCap() {
  const nT = 96, nR = 30;
  capRads = [];
  for (let i = 0; i <= nT; i++) capRads.push(capRadius(2 * Math.PI * (i % nT) / nT));
  const P = [], C = [], I = [];
  let zmin = Infinity, zmax = -Infinity;
  const zs = [];
  for (let i = 0; i <= nT; i++) {
    const th = 2 * Math.PI * (i % nT) / nT, cx = Math.cos(th), sy = Math.sin(th);
    for (let j = 0; j <= nR; j++) {
      const r = capRads[i] * j / nR;
      const x = r * cx, y = r * sy;
      let z = okc(x, y); if (!Number.isFinite(z)) z = 0;
      z = Math.max(z, 0);
      const w = M(x, y, z);
      P.push(w.x, w.y, w.z);
      zs.push(z);
      if (z < zmin) zmin = z; if (z > zmax) zmax = z;
    }
  }
  const span = Math.max(1e-6, zmax - zmin);
  for (const z of zs) { const c = ramp((z - zmin) / span); C.push(c.r, c.g, c.b); }
  const row = nR + 1;
  for (let i = 0; i < nT; i++) for (let j = 0; j < nR; j++) {
    const a = i * row + j, b = (i + 1) * row + j;
    I.push(a, b, a + 1, b, b + 1, a + 1);
  }
  setGeom(capMesh, gridGeom(P, C, I));
  hasCap = zmax > 0.01;
}

function buildShadow() {
  if (!capRads) { hasCap = false; return; }
  const nT = capRads.length - 1;
  const P = [0, 0.001, 0], I = [], L = [];
  for (let i = 0; i <= nT; i++) {
    const th = 2 * Math.PI * (i % nT) / nT;
    const x = capRads[i] * Math.cos(th), y = capRads[i] * Math.sin(th);
    const w = M(x, y, 0.001);
    P.push(w.x, w.y, w.z);
    if (i < nT) L.push(w.x, w.y, w.z);
  }
  for (let i = 1; i <= nT; i++) I.push(0, i, i + 1);
  setGeom(shadowMesh, gridGeom(P, null, I));
  const lg = new THREE.BufferGeometry();
  lg.setAttribute('position', new THREE.Float32BufferAttribute(L, 3));
  setGeom(shadowEdge, lg);
}

/* ── cylinder wall: (boundary point, s · zcut) ──────────────────────────── */
function buildWall() {
  if (!BND) { hasWall = false; hasCurve = false; return; }
  const B = BND.pts, nT = B.length, nS = 18;
  const P = [], I = [];
  let zmax = 0;
  for (let i = 0; i <= nT; i++) {
    const p = B[i % nT];
    let zt = okc(p.x, p.y); if (!Number.isFinite(zt)) zt = 0;
    zt = Math.max(zt, 0);
    if (zt > zmax) zmax = zt;
    for (let j = 0; j <= nS; j++) {
      const w = M(p.x, p.y, zt * j / nS);
      P.push(w.x, w.y, w.z);
    }
  }
  const row = nS + 1, I2 = I;
  for (let i = 0; i < nT; i++) for (let j = 0; j < nS; j++) {
    const a = i * row + j, b = (i + 1) * row + j;
    I2.push(a, b, a + 1, b, b + 1, a + 1);
  }
  const geo = gridGeom(P, null, I2);
  setGeom(wallF, geo);
  wallB.geometry = geo;           // shared geometry, back-face material
  hasWall = zmax > 0.02;
}

function buildCurve() {
  if (!BND) { hasCurve = false; return; }
  const pts = BND.pts.map(p => {
    let z = okc(p.x, p.y); if (!Number.isFinite(z)) z = 0;
    return M(p.x, p.y, Math.max(z, 0));
  });
  const curve = new THREE.CatmullRomCurve3(pts, true, 'centripetal', 0.3);
  setGeom(curveMesh, new THREE.TubeGeometry(curve, Math.max(64, pts.length), 0.028, 8, true));
  hasCurve = true;
}

function buildDisk() {
  if (!BND) { hasDisk = false; return; }
  const B = BND.pts, s = BND.seed;
  const c = M(s.x, s.y, 0.004);
  const P = [c.x, c.y, c.z], I = [], L = [];
  for (let i = 0; i <= B.length; i++) {
    const p = B[i % B.length];
    const w = M(p.x, p.y, 0.004);
    P.push(w.x, w.y, w.z);
    if (i < B.length) L.push(w.x, w.y, w.z);
  }
  for (let i = 1; i <= B.length; i++) I.push(0, i, i + 1);
  setGeom(diskMesh, gridGeom(P, null, I));
  const lg = new THREE.BufferGeometry();
  lg.setAttribute('position', new THREE.Float32BufferAttribute(L, 3));
  setGeom(diskEdge, lg);
  hasDisk = true;
}

/* ── horizontal slice: {g ≤ 1} ∩ {cap ≥ z} at height z ──────────────────── */
function buildSlice(zc) {
  hasSlice = false;
  if (!BND || zc <= 0.01) return;
  const ins = (x, y) => {
    const gv = okg(x, y), cv = okc(x, y);
    return Number.isFinite(gv) && gv <= 1 && Number.isFinite(cv) && cv >= zc;
  };
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (const p of BND.pts) {
    x0 = Math.min(x0, p.x); x1 = Math.max(x1, p.x);
    y0 = Math.min(y0, p.y); y1 = Math.max(y1, p.y);
  }
  let best = null;
  const N = 44;
  for (let i = 0; i <= N; i++) for (let j = 0; j <= N; j++) {
    const x = x0 + (x1 - x0) * i / N, y = y0 + (y1 - y0) * j / N;
    const gv = okg(x, y), cv = okc(x, y);
    if (!Number.isFinite(gv) || !Number.isFinite(cv)) continue;
    const s = Math.min(1 - gv, cv - zc);
    if (s > 0 && (!best || s > best.s)) best = { x, y, s };
