    new THREE.LineBasicMaterial({ color }));
}

function buildAxes() {
  const BLK = 0x000000;
  // z-axis: dashed where it passes through the solid (0 → 4), solid above
  gAxes.add(dashedSeg(M(0, 0, 0), M(0, 0, 4), BLK));
  gAxes.add(rod(M(0, 0, 4), M(0, 0, 5.05), 0.013, BLK));
  gAxes.add(coneHead(M(0, 0, 5.25), M(0, 0, 1).sub(M(0, 0, 0)), BLK));
  // y-axis: dashed under the cap (0 → 2), solid beyond
  gAxes.add(dashedSeg(M(0, 0, 0), M(0, 2, 0), BLK));
  gAxes.add(rod(M(0, 2, 0), M(0, 3.15, 0), 0.013, BLK));
  gAxes.add(coneHead(M(0, 3.35, 0), M(0, 1, 0), BLK));
  // x-axis: dashed under the solid (0 → 2), solid beyond
  gAxes.add(dashedSeg(M(0, 0, 0), M(2, 0, 0), BLK));
  gAxes.add(rod(M(2, 0, 0), M(3.15, 0, 0), 0.013, BLK));
  gAxes.add(coneHead(M(3.35, 0, 0), M(1, 0, 0), BLK));
