const okc = (x, y) => { const v = capFn(x, y); return Number.isFinite(v) ? v : NaN; };
const okg = (x, y) => { const v = gFn(x, y); return Number.isFinite(v) ? v : NaN; };

/* ── footprint boundary  g(x,y) = 1  (radial marching from an interior seed) */
let BND = null;
function findSeed() {
  let best = null;
  const N = 80;
  for (let i = 0; i <= N; i++) for (let j = 0; j <= N; j++) {
    const x = -3 + 6 * i / N, y = -3 + 6 * j / N;
    const v = okg(x, y);
    if (!Number.isFinite(v)) continue;
    if (!best || v < best.v) best = { x, y, v };
  }
  return best;
}
function computeBoundary(nT) {
  const seed = findSeed();
  if (!seed || seed.v > 1) return null;
  const pts = [];
  for (let i = 0; i < nT; i++) {
    const th = 2 * Math.PI * i / nT, cx = Math.cos(th), sy = Math.sin(th);
    let lo = 0, hi = 4;
    for (let r = 0.04; r <= 4; r += 0.04) {
      const v = okg(seed.x + r * cx, seed.y + r * sy);
      if (!(Number.isFinite(v) && v <= 1)) { hi = r; break; }
      lo = r;
    }
    for (let k = 0; k < 20; k++) {
      const m = 0.5 * (lo + hi);
      const v = okg(seed.x + m * cx, seed.y + m * sy);
      if (Number.isFinite(v) && v <= 1) lo = m; else hi = m;
    }
    pts.push({ x: seed.x + lo * cx, y: seed.y + lo * sy });
  }
  return { seed, pts };
}

/* ── paraboloid cap  z = capFn(x,y)  over its own z ≥ 0 footprint ───────── */
let capRads = null;
function capRadius(th) {
  const cx = Math.cos(th), sy = Math.sin(th);
  if (!(okc(0, 0) > 0)) return 2;
  let lo = 0, hi = 3.4;
  for (let r = 0.04; r <= 3.4; r += 0.04) {
    const v = okc(r * cx, r * sy);
    if (!(Number.isFinite(v) && v >= 0)) { hi = r; break; }
    lo = r;
  }
  for (let k = 0; k < 18; k++) {
    const m = 0.5 * (lo + hi);
    const v = okc(m * cx, m * sy);
    if (Number.isFinite(v) && v >= 0) lo = m; else hi = m;
  }
  return Math.max(0.05, lo);
}

function buildCap() {
  const nT = 96, nR = 30;
  capRads = [];
  for (let i = 0; i <= nT; i++) capRads.push(capRadius(2 * Math.PI * (i % nT) / nT));
  const P = [], C = [], I = [];
  let zmin = Infinity, zmax = -Infinity;
  const zs = [];
  for (let i = 0; i <= nT; i++) {
    const th = 2 * Math.PI * (i % nT) / nT, cx = Math.cos(th), sy = Math.sin(th);
    for (let j = 0; j <= nR; j++) {
      const r = capRads[i] * j / nR;
      const x = r * cx, y = r * sy;
      let z = okc(x, y); if (!Number.isFinite(z)) z = 0;
      z = Math.max(z, 0);
      const w = M(x, y, z);
      P.push(w.x, w.y, w.z);
      zs.push(z);
      if (z < zmin) zmin = z; if (z > zmax) zmax = z;
    }
  }
  const span = Math.max(1e-6, zmax - zmin);
  for (const z of zs) { const c = ramp((z - zmin) / span); C.push(c.r, c.g, c.b); }
  const row = nR + 1;
  for (let i = 0; i < nT; i++) for (let j = 0; j < nR; j++) {
    const a = i * row + j, b = (i + 1) * row + j;
    I.push(a, b, a + 1, b, b + 1, a + 1);
  }
  setGeom(capMesh, gridGeom(P, C, I));
  hasCap = zmax > 0.01;
}

function buildShadow() {
  if (!capRads) { hasCap = false; return; }
  const nT = capRads.length - 1;
  const P = [0, 0.001, 0], I = [], L = [];
  for (let i = 0; i <= nT; i++) {
    const th = 2 * Math.PI * (i % nT) / nT;
    const x = capRads[i] * Math.cos(th), y = capRads[i] * Math.sin(th);
    const w = M(x, y, 0.001);
    P.push(w.x, w.y, w.z);
    if (i < nT) L.push(w.x, w.y, w.z);
  }
  for (let i = 1; i <= nT; i++) I.push(0, i, i + 1);
  setGeom(shadowMesh, gridGeom(P, null, I));
  const lg = new THREE.BufferGeometry();
  lg.setAttribute('position', new THREE.Float32BufferAttribute(L, 3));
  setGeom(shadowEdge, lg);
}

/* ── cylinder wall: (boundary point, s · zcut) ──────────────────────────── */
function buildWall() {
  if (!BND) { hasWall = false; hasCurve = false; return; }
  const B = BND.pts, nT = B.length, nS = 18;
  const P = [], I = [];
  let zmax = 0;
  for (let i = 0; i <= nT; i++) {
    const p = B[i % nT];
    let zt = okc(p.x, p.y); if (!Number.isFinite(zt)) zt = 0;
    zt = Math.max(zt, 0);
    if (zt > zmax) zmax = zt;
    for (let j = 0; j <= nS; j++) {
      const w = M(p.x, p.y, zt * j / nS);
      P.push(w.x, w.y, w.z);
    }
  }
  const row = nS + 1, I2 = I;
  for (let i = 0; i < nT; i++) for (let j = 0; j < nS; j++) {
    const a = i * row + j, b = (i + 1) * row + j;
    I2.push(a, b, a + 1, b, b + 1, a + 1);
  }
  const geo = gridGeom(P, null, I2);
  setGeom(wallF, geo);
  wallB.geometry = geo;           // shared geometry, back-face material
  hasWall = zmax > 0.02;
}

function buildCurve() {
  if (!BND) { hasCurve = false; return; }
  const pts = BND.pts.map(p => {
    let z = okc(p.x, p.y); if (!Number.isFinite(z)) z = 0;
    return M(p.x, p.y, Math.max(z, 0));
  });
  const curve = new THREE.CatmullRomCurve3(pts, true, 'centripetal', 0.3);
  setGeom(curveMesh, new THREE.TubeGeometry(curve, Math.max(64, pts.length), 0.028, 8, true));
  hasCurve = true;
}

function buildDisk() {
  if (!BND) { hasDisk = false; return; }
  const B = BND.pts, s = BND.seed;
  const c = M(s.x, s.y, 0.004);
  const P = [c.x, c.y, c.z], I = [], L = [];
  for (let i = 0; i <= B.length; i++) {
    const p = B[i % B.length];
    const w = M(p.x, p.y, 0.004);
    P.push(w.x, w.y, w.z);
    if (i < B.length) L.push(w.x, w.y, w.z);
  }
  for (let i = 1; i <= B.length; i++) I.push(0, i, i + 1);
  setGeom(diskMesh, gridGeom(P, null, I));
  const lg = new THREE.BufferGeometry();
  lg.setAttribute('position', new THREE.Float32BufferAttribute(L, 3));
  setGeom(diskEdge, lg);
  hasDisk = true;
}

/* ── horizontal slice: {g ≤ 1} ∩ {cap ≥ z} at height z ──────────────────── */
function buildSlice(zc) {
  hasSlice = false;
  if (!BND || zc <= 0.01) return;
  const ins = (x, y) => {
    const gv = okg(x, y), cv = okc(x, y);
    return Number.isFinite(gv) && gv <= 1 && Number.isFinite(cv) && cv >= zc;
  };
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (const p of BND.pts) {
    x0 = Math.min(x0, p.x); x1 = Math.max(x1, p.x);
    y0 = Math.min(y0, p.y); y1 = Math.max(y1, p.y);
  }
  let best = null;
  const N = 44;
  for (let i = 0; i <= N; i++) for (let j = 0; j <= N; j++) {
    const x = x0 + (x1 - x0) * i / N, y = y0 + (y1 - y0) * j / N;
    const gv = okg(x, y), cv = okc(x, y);
    if (!Number.isFinite(gv) || !Number.isFinite(cv)) continue;
    const s = Math.min(1 - gv, cv - zc);
    if (s > 0 && (!best || s > best.s)) best = { x, y, s };
  }
  if (!best) return;
  const nT = 72, pts = [];
  for (let i = 0; i < nT; i++) {
    const th = 2 * Math.PI * i / nT, cx = Math.cos(th), sy = Math.sin(th);
    let lo = 0, hi = 3;
    for (let r = 0.03; r <= 3; r += 0.03) {
      if (!ins(best.x + r * cx, best.y + r * sy)) { hi = r; break; }
      lo = r;
    }
    for (let k = 0; k < 16; k++) {
      const m = 0.5 * (lo + hi);
      if (ins(best.x + m * cx, best.y + m * sy)) lo = m; else hi = m;
    }
    pts.push([best.x + lo * cx, best.y + lo * sy]);
  }
  const c = M(best.x, best.y, zc);
  const P = [c.x, c.y, c.z], I = [], L = [];
  for (let i = 0; i <= nT; i++) {
    const p = pts[i % nT];
    const w = M(p[0], p[1], zc);
    P.push(w.x, w.y, w.z);
    if (i < nT) L.push(w.x, w.y, w.z);
  }
  for (let i = 1; i <= nT; i++) I.push(0, i, i + 1);
  setGeom(sliceMesh, gridGeom(P, null, I));
  const lg = new THREE.BufferGeometry();
  lg.setAttribute('position', new THREE.Float32BufferAttribute(L, 3));
  setGeom(sliceEdge, lg);
  hasSlice = true;
}

/* ── axes, ticks, leader arrows (static) ────────────────────────────────── */
const gAxes = new THREE.Group();
scene.add(gAxes);

function rod(p1, p2, r, color) {
  const dir = new THREE.Vector3().subVectors(p2, p1);
  const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10),
    new THREE.MeshBasicMaterial({ color }));
  m.position.copy(p1).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}
function coneHead(tip, dir, color, rad = 0.075, h = 0.22) {
  const geo = new THREE.ConeGeometry(rad, h, 16);
  geo.translate(0, -h / 2, 0);
  const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color }));
  m.position.copy(tip);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}
function dashedSeg(p1, p2, color) {
  const g = new THREE.BufferGeometry().setFromPoints([p1, p2]);
  const l = new THREE.Line(g, new THREE.LineDashedMaterial({ color, dashSize: 0.13, gapSize: 0.1 }));
  l.computeLineDistances();
  return l;
}
function plainLine(pts, color) {
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color }));
}

function buildAxes() {
  const BLK = 0x000000;
  // z-axis: dashed where it passes through the solid (0 → 4), solid above
  gAxes.add(dashedSeg(M(0, 0, 0), M(0, 0, 4), BLK));
  gAxes.add(rod(M(0, 0, 4), M(0, 0, 5.05), 0.013, BLK));
  gAxes.add(coneHead(M(0, 0, 5.25), M(0, 0, 1).sub(M(0, 0, 0)), BLK));
  // y-axis: dashed under the cap (0 → 2), solid beyond
  gAxes.add(dashedSeg(M(0, 0, 0), M(0, 2, 0), BLK));
  gAxes.add(rod(M(0, 2, 0), M(0, 3.15, 0), 0.013, BLK));
  gAxes.add(coneHead(M(0, 3.35, 0), M(0, 1, 0), BLK));
  // x-axis: dashed under the solid (0 → 2), solid beyond
  gAxes.add(dashedSeg(M(0, 0, 0), M(2, 0, 0), BLK));
  gAxes.add(rod(M(2, 0, 0), M(3.15, 0, 0), 0.013, BLK));
  gAxes.add(coneHead(M(3.35, 0, 0), M(1, 0, 0), BLK));
  // tick at x = 2
  gAxes.add(plainLine([M(2, -0.1, 0), M(2, 0.1, 0)], BLK));

  // straight leader arrow: cap label → orange part of the cap
  const a0 = M(0, 2.85, 3.42), a1 = M(0, 1.05, 3.05);
  gAxes.add(plainLine([a0, a1], BLK));
  gAxes.add(coneHead(a1, new THREE.Vector3().subVectors(a1, a0), BLK, 0.06, 0.18));

  // curved leader arrow: base-ellipse label → front of the base disk
  const b0 = M(2.25, -0.15, -1.0), bc = M(1.95, -0.95, -0.42), b1 = M(1.34, -0.94, 0.03);
  const bez = new THREE.QuadraticBezierCurve3(b0, bc, b1);
  gAxes.add(new THREE.Mesh(new THREE.TubeGeometry(bez, 40, 0.014, 8, false),
    new THREE.MeshBasicMaterial({ color: BLK })));
  const tEnd = bez.getTangent(1);
  gAxes.add(coneHead(b1, tEnd, BLK, 0.055, 0.16));
}
buildAxes();

/* ── build everything once with the defaults ────────────────────────────── */
function rebuildAll() {
  BND = computeBoundary(128);
  buildCap();
  buildShadow();
  buildWall();
  buildCurve();
  buildDisk();
  buildSlice(sliceZ);
  applyVisibility();
}

/* ── visibility / highlight ─────────────────────────────────────────────── */
function fade(mat, base, on) {
  mat.opacity = on ? base : base * 0.15;
  mat.transparent = true;
  mat.depthWrite = on;
}
function applyVisibility() {
  const region = viewMode === 'region';
  const onAll = hlMode === 'All';

  capMesh.visible = !region && hasCap;
  wallF.visible = wallB.visible = !region && hasWall;
  curveMesh.visible = !region && hasCurve;
  shadowMesh.visible = shadowEdge.visible = !region && hasCap;
  sliceMesh.visible = sliceEdge.visible = !region && hasSlice && sliceZ > 0.01;
  diskMesh.visible = diskEdge.visible = hasDisk;

  fade(capMat, 0.9, onAll || hlMode === 'cap');
  fade(wallFMat, 0.75, onAll || hlMode === 'wall');
  fade(wallBMat, 0.92, onAll || hlMode === 'wall');
  fade(diskMat, 0.95, onAll || hlMode === 'disk' || region);
  fade(curveMat, 1.0, onAll || hlMode === 'curve');
  diskEdge.material.opacity = (onAll || hlMode === 'disk' || region) ? 1 : 0.25;
  diskEdge.material.transparent = true;
  if (hlMode === 'curve' && !region) { curveMesh.visible = hasCurve; }
}

rebuildAll();

/* ── camera (after geometry) ────────────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.72
});

/* ── labels ─────────────────────────────────────────────────────────────── */
addLabel('<b>z</b>', M(0, 0, 5.5), { fontSize: '15px' });
addLabel('<b>y</b>', M(0, 3.62, -0.05), { fontSize: '15px' });
addLabel('<b>x</b>', M(3.62, 0, -0.05), { fontSize: '15px' });
addLabel('0', M(0, 0, 0), { fontSize: '14px', offset: [16, 10] });
addLabel('2', M(2, 0, 0), { fontSize: '14px', offset: [-2, 20] });

const capLabel = addLabel('', M(0, 3.25, 3.62), { fontSize: '14px' });
const cylLabel = addLabel('', M(2.6, -0.2, -1.22), { fontSize: '14px' });

function prettify(s) {
  return String(s)
    .replace(/\*\*/g, '^')
    .replace(/x\s*\*\s*x/g, 'x²')
    .replace(/y\s*\*\s*y/g, 'y²')
    .replace(/\^\s*2/g, '²')
    .replace(/\^\s*3/g, '³')
    .replace(/\*/g, '·')
    .replace(/-/g, '−');
}
function updateEqLabels() {
  capLabel.div.innerHTML = 'z = ' + prettify(capSrc);
  cylLabel.div.innerHTML = prettify(gSrc) + ' = 1';
}
updateEqLabels();

/* ── hover / click explanations ─────────────────────────────────────────── */
registerInteractive(capMesh, {
  title: 'Paraboloid cap  z = 4 − x² − y²',
  tooltip: 'Top surface: height above the disk',
  body: 'The cap supplies the HEIGHT of the solid. Above each point (x, y) of the base disk the solid rises to z = 4 − x² − y². Its rim, where z = 0, is the circle x² + y² = 4 of radius 2 — wider than the disk, so the cap overhangs on every side.'
});
registerInteractive(wallF, {
  title: 'Cylinder wall  (x − 1)² + y² = 1',
  tooltip: 'Lateral boundary of the solid',
  body: 'The vertical wall is the base circle swept upward. It is cut off by the paraboloid, so the tube is open at the top: its rim rides from z = 4 above the origin down to z = 0 at (2, 0, 0).'
});
registerInteractive(diskMesh, {
  title: 'Base region  (x − 1)² + y² ≤ 1',
  tooltip: 'Region of integration in the xy-plane',
  body: 'A disk of radius 1 centred at (1, 0): it touches the origin and reaches x = 2. This disk supplies the LIMITS of the double integral, V = ∬ (4 − x² − y²) dA.'
});
registerInteractive(curveMesh, {
  title: 'Intersection curve',
  tooltip: 'Where the cylinder meets the paraboloid',
  body: 'Substituting x = 1 + cos t, y = sin t into z = 4 − x² − y² gives z = 2 − 2cos t, so the closed rim sweeps from z = 0 at t = 0 (the point (2,0)) up to z = 4 at t = π (the origin side).'
});

/* ── controls ───────────────────────────────────────────────────────────── */
const hlRow = document.getElementById('hlRow');
const viewRow = document.getElementById('viewRow');
const sliceInput = document.getElementById('sliceZ');
const szVal = document.getElementById('szVal');

function setHl(mode) {
  hlMode = mode;
  hlRow.querySelectorAll('button').forEach(b => b.classList.toggle('active', b.dataset.hl === mode));
  applyVisibility();
}
function setView(mode) {
  viewMode = mode;
  viewRow.querySelectorAll('button').forEach(b => b.classList.toggle('active', b.dataset.view === mode));
  applyVisibility();
}
hlRow.addEventListener('click', e => { if (e.target.dataset.hl) setHl(e.target.dataset.hl); });
viewRow.addEventListener('click', e => { if (e.target.dataset.view) setView(e.target.dataset.view); });

let slicePending = false;
function setSlice(v, syncInput) {
  sliceZ = Math.max(0, Math.min(4, v));
  szVal.textContent = sliceZ.toFixed(2);
  if (syncInput) sliceInput.value = sliceZ;
  if (!slicePending) {
    slicePending = true;
    requestAnimationFrame(() => {
      slicePending = false;
      buildSlice(sliceZ);
      applyVisibility();
    });
  }
}
sliceInput.addEventListener('input', () => setSlice(parseFloat(sliceInput.value), false));

/* ── equation inputs (scaffold-owned parsing & re-sampling) ─────────────── */
bindEquationInput('capEq', (fn, src) => { capFn = fn; capSrc = src; }, {
  variables: ['x', 'y'],
  onChange: () => { updateEqLabels(); rebuildAll(); }
});
bindEquationInput('cylEq', (fn, src) => { gFn = fn; gSrc = src; }, {
  variables: ['x', 'y'],
  onChange: () => { updateEqLabels(); rebuildAll(); }
});

/* ── guided tour ────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: '1. The base region',
    text: 'Only the disk (x − 1)² + y² ≤ 1 is shown, lying in the xy-plane: a circle of radius 1 centred at (1, 0), touching the origin and reaching x = 2. This is the region of integration.',
    view: 'region', hl: 'disk', z: 0
  },
  {
    title: '2. Extrude to the cylinder',
    text: 'The disk sweeps upward into the vertical cylinder wall. Its side is the surface (x − 1)² + y² = 1 — the lateral boundary of the solid.',
    view: 'solid', hl: 'wall', z: 0
  },
  {
    title: '3. Cap it with the paraboloid',
    text: 'The downward-opening paraboloid z = 4 − x² − y² slices the tube off, leaving a hollow open top. The height above each point of the disk is 4 − x² − y².',
    view: 'solid', hl: 'cap', z: 0
  },
  {
    title: '4. Where the surfaces meet',
    text: 'The closed curve where cylinder and paraboloid intersect rides high above the origin side and dips to z = 0 at x = 2 — the tilted rim of the open top.',
    view: 'solid', hl: 'curve', z: 0
  },
  {
    title: '5. Stacking slices',
    text: 'Raise the horizontal plane: the cross-section is the part of the disk with 4 − x² − y² ≥ z. It shrinks and vanishes near z = 4, and the sum of all slices is the volume ∬ (4 − x² − y²) dA.',
    view: 'solid', hl: 'All', z: 2.5
  }
];
let stepIdx = -1;
let tweenId = null;
const tourTitle = document.getElementById('tourTitle');
const tourText = document.getElementById('tourText');

function tweenSlice(target) {
  cancelAnimationFrame(tweenId);
  const start = sliceZ, t0 = performance.now(), dur = 650;
  (function step() {
    const k = Math.min(1, (performance.now() - t0) / dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    setSlice(start + (target - start) * e, true);
    if (k < 1) tweenId = requestAnimationFrame(step);
  })();
}
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setView(s.view);
  setHl(s.hl);
  tweenSlice(s.z);
  tourTitle.textContent = s.title;
  tourText.textContent = s.text;
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

tourTitle.textContent = 'Drag to orbit';
tourText.textContent = 'The cylinder sits off-centre inside the paraboloid, tangent to the z-axis at the origin, so the cap overhangs the disk on all sides. Press “Next ▶” to walk through the construction.';
// @FIGURE_CODE_END

