const okc = (x, y) => { const v = capFn(x, y); return Number.isFinite(v) ? v : NaN; };
const okg = (x, y) => { const v = gFn(x, y); return Number.isFinite(v) ? v : NaN; };

/* ── footprint boundary  g(x,y) = 1 ─────────────────────────────────────── */
let BND = null;
function findSeed() {
  let best = null; const N = 70;
  for (let i = 0; i <= N; i++) for (let j = 0; j <= N; j++) {
    const x = -3 + 6 * i / N, y = -3 + 6 * j / N;
    const v = okg(x, y);
    if (!Number.isFinite(v)) continue;
    if (!best || v < best.v) best = { x, y, v };
  }
  return best;
}
function computeBoundary(nT) {
  const seed = findSeed();
  if (!seed || seed.v > 1) return null;
  const pts = [];
  for (let i = 0; i < nT; i++) {
    const th = 2 * Math.PI * i / nT, cx = Math.cos(th), sy = Math.sin(th);
    let lo = 0, hi = 4;
    for (let r = 0.04; r <= 4; r += 0.04) {
      const v = okg(seed.x + r * cx, seed.y + r * sy);
      if (!(Number.isFinite(v) && v <= 1)) { hi = r; break; }
      lo = r;
    }
    for (let k = 0; k < 20; k++) {
      const m = 0.5 * (lo + hi);
      const v = okg(seed.x + m * cx, seed.y + m * sy);
      if (Number.isFinite(v) && v <= 1) lo = m; else hi = m;
    }
    pts.push({ x: seed.x + lo * cx, y: seed.y + lo * sy });
  }
  return { seed, pts };
}

/* ── paraboloid cap: annulus from the disk footprint out to z = 0 ──────── */
let capRads = null;
function capRadius(th) {
  const cx = Math.cos(th), sy = Math.sin(th);
  if (!(okc(0, 0) > 0)) return 2;
  let lo = 0, hi = 3.4;
  for (let r = 0.05; r <= 3.4; r += 0.05) {
    const v = okc(r * cx, r * sy);
    if (!(Number.isFinite(v) && v >= 0)) { hi = r; break; }
    lo = r;
  }
  for (let k = 0; k < 16; k++) {
    const m = 0.5 * (lo + hi);
    const v = okc(m * cx, m * sy);
    if (Number.isFinite(v) && v >= 0) lo = m; else hi = m;
  }
  return Math.max(0.05, lo);
}
// radius (from the math origin) where the ray first meets the disk g ≤ 1,
// marching INWARD from the cap rim; 0 if the ray misses the disk entirely.
function holeRadius(th, R) {
  const cx = Math.cos(th), sy = Math.sin(th);
  const steps = 60; let hi = R, lo = -1;
  for (let k = 0; k <= steps; k++) {
    const r = R * (1 - k / steps);
    const v = okg(r * cx, r * sy);
    if (Number.isFinite(v) && v <= 1) { lo = r; break; }
    hi = r;
  }
  if (lo < 0) return 0;
  for (let k = 0; k < 18; k++) {
    const m = 0.5 * (lo + hi);
    const v = okg(m * cx, m * sy);
    if (Number.isFinite(v) && v <= 1) lo = m; else hi = m;
  }
  return 0.5 * (lo + hi);
}

function buildCap() {
  const nT = 150, nR = 22;
  capRads = []; const inner = [];
  for (let i = 0; i <= nT; i++) {
    const th = 2 * Math.PI * (i % nT) / nT;
    const R = capRadius(th);
    capRads.push(R);
    inner.push(holeRadius(th, R));
  }
  const P = [], C = [], I = [], zs = [];
  let zmax = 0, widest = 0;
  for (let i = 0; i <= nT; i++) {
    const th = 2 * Math.PI * (i % nT) / nT, cx = Math.cos(th), sy = Math.sin(th);
    const r0 = inner[i], r1 = capRads[i];
    widest = Math.max(widest, r1 - r0);
    for (let j = 0; j <= nR; j++) {
      const r = r0 + (r1 - r0) * j / nR;
      const x = r * cx, y = r * sy;
      let z = okc(x, y); if (!Number.isFinite(z)) z = 0;
      z = Math.max(z, 0);
      const w = M(x, y, z);
      P.push(w.x, w.y, w.z); zs.push(z);
      if (z > zmax) zmax = z;
    }
  }
  const span = Math.max(1e-6, zmax);
  for (const z of zs) { const c = ramp(z / span); C.push(c.r, c.g, c.b); }
  const row = nR + 1;
  for (let i = 0; i < nT; i++) for (let j = 0; j < nR; j++) {
    const a = i * row + j, b = (i + 1) * row + j;
    I.push(a, b, a + 1, b, b + 1, a + 1);
  }
  setGeom(capMesh, gridGeom(P, C, I));
  hasCap = widest > 0.02 && zmax > 0.05;

  // ground rim of the cap (the big ellipse at z = 0)
  const rp = [];
  for (let i = 0; i < nT; i++) {
    const th = 2 * Math.PI * i / nT;
    rp.push(M(capRads[i] * Math.cos(th), capRads[i] * Math.sin(th), 0.007));
  }
  const rc = new THREE.CatmullRomCurve3(rp, true, 'centripetal', 0.5);
  setGeom(rimRing, new THREE.TubeGeometry(rc, 180, 0.013, 6, true));
}

/* ── cylinder wall ──────────────────────────────────────────────────────── */
function buildWall() {
  gSil.clear();
  if (!BND) { hasWall = false; return; }
  const B = BND.pts, nT = B.length, nS = 16;
  const P = [], C = [], I = [];
  let zmax = 0;
  const tops = [];
  for (let i = 0; i <= nT; i++) {
    const p = B[i % nT];
    let zt = okc(p.x, p.y); if (!Number.isFinite(zt)) zt = 0;
    zt = Math.max(zt, 0); tops.push(zt);
    if (zt > zmax) zmax = zt;
  }
  for (let i = 0; i <= nT; i++) {
    const p = B[i % nT], zt = tops[i];
    for (let j = 0; j <= nS; j++) {
      const f = j / nS;
      const w = M(p.x, p.y, zt * f);
      P.push(w.x, w.y, w.z);
      const c = _cA.copy(WALL_LO).lerp(_cB.copy(WALL_HI), Math.min(1, (zt * f) / 4));
      C.push(c.r, c.g, c.b);
    }
  }
  const row = nS + 1;
  for (let i = 0; i < nT; i++) for (let j = 0; j < nS; j++) {
    const a = i * row + j, b = (i + 1) * row + j;
    I.push(a, b, a + 1, b, b + 1, a + 1);
  }
  const geo = gridGeom(P, C, I);
  setGeom(wallF, geo);
  wallB.geometry = geo;
  hasWall = zmax > 0.02;

  // silhouette generators at the extreme-y boundary points
  let iMax = 0, iMin = 0;
  for (let i = 0; i < nT; i++) {
    if (B[i].y > B[iMax].y) iMax = i;
    if (B[i].y < B[iMin].y) iMin = i;
  }
  for (const i of [iMax, iMin]) {
    const p = B[i], zt = tops[i];
    if (zt < 0.05) continue;
    const g = new THREE.CylinderGeometry(0.014, 0.014, zt, 8);
    const m = new THREE.Mesh(g, silMat);
    const w = M(p.x, p.y, zt / 2);
    m.position.copy(w);
    gSil.add(m);
  }
}

function buildCurve() {
  if (!BND) { hasCurve = false; return; }
  const pts = BND.pts.map(p => {
    let z = okc(p.x, p.y); if (!Number.isFinite(z)) z = 0;
    return M(p.x, p.y, Math.max(z, 0));
  });
  const curve = new THREE.CatmullRomCurve3(pts, true, 'centripetal', 0.4);
  setGeom(curveMesh, new THREE.TubeGeometry(curve, Math.max(96, pts.length), 0.021, 8, true));
  hasCurve = true;
}

function buildDisk() {
  if (!BND) { hasDisk = false; return; }
  const B = BND.pts, s = BND.seed;
  const c = M(s.x, s.y, 0.004);
  const P = [c.x, c.y, c.z], I = [], L = [];
  for (let i = 0; i <= B.length; i++) {
    const p = B[i % B.length];
    const w = M(p.x, p.y, 0.004);
    P.push(w.x, w.y, w.z);
    if (i < B.length) L.push(M(p.x, p.y, 0.012));
  }
  for (let i = 1; i <= B.length; i++) I.push(0, i, i + 1);
  setGeom(diskMesh, gridGeom(P, null, I));
  const rc = new THREE.CatmullRomCurve3(L, true, 'centripetal', 0.4);
  setGeom(diskRing, new THREE.TubeGeometry(rc, Math.max(96, L.length), 0.018, 8, true));
  hasDisk = true;
}

/* ── horizontal slice ───────────────────────────────────────────────────── */
function buildSlice(zc) {
  hasSlice = false;
  if (!BND || zc <= 0.02) return;
  const ins = (x, y) => {
    const gv = okg(x, y), cv = okc(x, y);
    return Number.isFinite(gv) && gv <= 1 && Number.isFinite(cv) && cv >= zc;
  };
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (const p of BND.pts) {
    x0 = Math.min(x0, p.x); x1 = Math.max(x1, p.x);
    y0 = Math.min(y0, p.y); y1 = Math.max(y1, p.y);
  }
  let best = null; const N = 40;
  for (let i = 0; i <= N; i++) for (let j = 0; j <= N; j++) {
    const x = x0 + (x1 - x0) * i / N, y = y0 + (y1 - y0) * j / N;
    const gv = okg(x, y), cv = okc(x, y);
    if (!Number.isFinite(gv) || !Number.isFinite(cv)) continue;
    const s = Math.min(1 - gv, cv - zc);
    if (s > 0 && (!best || s > best.s)) best = { x, y, s };
  }
  if (!best) return;
  const nT = 64, pts = [];
  for (let i = 0; i < nT; i++) {
    const th = 2 * Math.PI * i / nT, cx = Math.cos(th), sy = Math.sin(th);
    let lo = 0, hi = 3;
    for (let r = 0.03; r <= 3; r += 0.03) {
      if (!ins(best.x + r * cx, best.y + r * sy)) { hi = r; break; }
      lo = r;
    }
    for (let k = 0; k < 15; k++) {
      const m = 0.5 * (lo + hi);
      if (ins(best.x + m * cx, best.y + m * sy)) lo = m; else hi = m;
    }
    pts.push([best.x + lo * cx, best.y + lo * sy]);
  }
  const c = M(best.x, best.y, zc);
  const P = [c.x, c.y, c.z], I = [], L = [];
  for (let i = 0; i <= nT; i++) {
    const p = pts[i % nT];
    const w = M(p[0], p[1], zc);
    P.push(w.x, w.y, w.z);
    if (i < nT) L.push(w.x, w.y, w.z);
  }
  for (let i = 1; i <= nT; i++) I.push(0, i, i + 1);
  setGeom(sliceMesh, gridGeom(P, null, I));
  const lg = new THREE.BufferGeometry();
  lg.setAttribute('position', new THREE.Float32BufferAttribute(L, 3));
  setGeom(sliceEdge, lg);
  hasSlice = true;
}

/* ── axes, ticks, leader arrows (static) ────────────────────────────────── */
const gAxes = new THREE.Group();
scene.add(gAxes);

function rod(p1, p2, r, color) {
  const dir = new THREE.Vector3().subVectors(p2, p1);
  const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10),
    new THREE.MeshBasicMaterial({ color }));
  m.position.copy(p1).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}
function coneHead(tip, dir, color, rad = 0.075, h = 0.22) {
  const geo = new THREE.ConeGeometry(rad, h, 16);
  geo.translate(0, -h / 2, 0);
  const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color }));
  m.position.copy(tip);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}
function dashedSeg(p1, p2, color) {
  const g = new THREE.BufferGeometry().setFromPoints([p1, p2]);
  const mat = new THREE.LineDashedMaterial({ color, dashSize: 0.14, gapSize: 0.11, depthTest: false, transparent: true, opacity: 0.85 });
  const l = new THREE.Line(g, mat);
  l.computeLineDistances();
  l.renderOrder = 6;
  return l;
}
function plainLine(pts, color) {
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color }));
}

function buildAxes() {
  const BLK = 0x000000;
  gAxes.add(dashedSeg(M(0, 0, 0), M(0, 0, 4.05), BLK));
  gAxes.add(rod(M(0, 0, 4.05), M(0, 0, 5.0), 0.013, BLK));
  gAxes.add(coneHead(M(0, 0, 5.22), new THREE.Vector3(0, 1, 0), BLK));

  gAxes.add(dashedSeg(M(0, 0, 0), M(0, 2.05, 0), BLK));
  gAxes.add(rod(M(0, 2.05, 0), M(0, 3.1, 0), 0.013, BLK));
  gAxes.add(coneHead(M(0, 3.32, 0), M(0, 1, 0).sub(M(0, 0, 0)), BLK));

  gAxes.add(dashedSeg(M(0, 0, 0), M(2.05, 0, 0), BLK));
  gAxes.add(rod(M(2.05, 0, 0), M(3.1, 0, 0), 0.013, BLK));
  gAxes.add(coneHead(M(3.32, 0, 0), M(1, 0, 0).sub(M(0, 0, 0)), BLK));

  gAxes.add(plainLine([M(2, -0.11, 0), M(2, 0.11, 0)], BLK));

  // leader arrow for the cap equation
  const a0 = M(-0.15, 3.05, 3.35), a1 = M(0.0, 1.25, 2.45);
  gAxes.add(plainLine([a0, a1], BLK));
  gAxes.add(coneHead(a1, new THREE.Vector3().subVectors(a1, a0), BLK, 0.06, 0.18));

  // curved leader arrow for the base-circle equation
  const b0 = M(2.45, -0.35, -0.95), bc = M(2.25, 0.25, -0.5), b1 = M(1.80, 0.52, 0.03);
  const bez = new THREE.QuadraticBezierCurve3(b0, bc, b1);
  gAxes.add(new THREE.Mesh(new THREE.TubeGeometry(bez, 40, 0.014, 8, false),
    new THREE.MeshBasicMaterial({ color: BLK })));
  gAxes.add(coneHead(b1, bez.getTangent(1), BLK, 0.055, 0.16));
}
buildAxes();

/* ── rebuild ────────────────────────────────────────────────────────────── */
function rebuildAll() {
  BND = computeBoundary(120);
  buildCap();
  buildWall();
  buildCurve();
  buildDisk();
  buildSlice(sliceZ);
  applyVisibility();
}

/* ── visibility / highlight ─────────────────────────────────────────────── */
function setOpacity(mat, op) {
  mat.opacity = op;
  mat.transparent = op < 0.999;
  mat.depthWrite = op > 0.6;
  mat.needsUpdate = true;
}
function applyVisibility() {
  const region = viewMode === 'region';
  const onAll = hlMode === 'All';
  const xray = !region && sliceZ > 0.02 && hasSlice;

  capMesh.visible = !region && hasCap;
  rimRing.visible = !region && hasCap;
  wallF.visible = wallB.visible = !region && hasWall;
  gSil.visible = !region && hasWall;
  curveMesh.visible = !region && hasCurve;
  sliceMesh.visible = sliceEdge.visible = !region && hasSlice;
  diskMesh.visible = hasDisk && (region || hlMode === 'disk');
  diskRing.visible = hasDisk;

  const capOn = onAll || hlMode === 'cap';
  const wallOn = onAll || hlMode === 'wall';
  const diskOn = onAll || hlMode === 'disk' || region;
  const curveOn = onAll || hlMode === 'curve';

  setOpacity(capMat, capOn ? (hlMode === 'wall' || hlMode === 'curve' ? 0.35 : 1) : 0.18);
  setOpacity(wallFMat, wallOn ? (xray ? 0.42 : 1) : 0.16);
  setOpacity(wallBMat, wallOn ? (xray ? 0.55 : 1) : 0.16);
  setOpacity(silMat, wallOn ? 1 : 0.18);
  setOpacity(rimMat, capOn ? 1 : 0.25);
  setOpacity(diskMat, diskOn ? 1 : 0.2);
  setOpacity(diskRingMat, diskOn ? 1 : 0.22);
  setOpacity(curveMat, curveOn ? 1 : 0.28);
  curveMat.color.setHex(hlMode === 'curve' ? 0xD95F2B : 0x2F4A6B);
  if (hlMode === 'curve') curveMesh.visible = !region && hasCurve;
}

rebuildAll();

