});

/* ── labels ─────────────────────────────────────────────────────────────── */
addLabel('<b>z</b>', M(0, 0, 5.55), { fontSize: '15px' });
addLabel('<b>y</b>', M(0, 3.62, -0.08), { fontSize: '15px' });
addLabel('<b>x</b>', M(3.62, 0, -0.08), { fontSize: '15px' });
