const capLabel = addLabel('', M(-0.2, 3.3, 3.55), { fontSize: '14px' });
const cylLabel = addLabel('', M(2.6, -0.55, -1.1), { fontSize: '14px' });

function prettify(s) {
  return String(s)
    .replace(/\*\*/g, '^')
    .replace(/x\s*\*\s*x/g, 'x²')
    .replace(/y\s*\*\s*y/g, 'y²')
    .replace(/\^\s*2/g, '²')
    .replace(/\^\s*3/g, '³')
    .replace(/\*/g, '·')
    .replace(/-/g, '−');
}
function updateEqLabels() {
  capLabel.div.innerHTML = 'z = ' + prettify(capSrc);
