const gSil = new THREE.Group(); gRoot.add(gSil);
const silMat = new THREE.MeshBasicMaterial({ color: 0x33587F });
const silHidMat = new THREE.LineDashedMaterial({
  color: 0x4C749C, dashSize: 0.13, gapSize: 0.10, transparent: true, opacity: 0.6, depthTest: false
