gRoot.add(diskMesh);
const diskRingMat = new THREE.MeshBasicMaterial({ color: 0x33587F });
const diskRing = new THREE.Mesh(new THREE.BufferGeometry(), diskRingMat);
gRoot.add(diskRing);
const diskHidMat = new THREE.LineDashedMaterial({
