const sliceEdgeMat = new THREE.LineBasicMaterial({ color: 0x9C4415, transparent: true, opacity: 0.95 });
const sliceEdge = new THREE.LineLoop(new THREE.BufferGeometry(), sliceEdgeMat);
sliceEdge.renderOrder = 4;
gRoot.add(sliceEdge);

let hasCap = false, hasWall = false, hasDisk = false, hasCurve = false, hasSlice = false;

/* ── small helpers ──────────────────────────────────────────────────────── */
function setGeom(mesh, geo) { mesh.geometry.dispose(); mesh.geometry = geo; }
function gridGeom(pos, col, idx) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  if (col) g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
