}

const RAMP = [
  [0.00, new THREE.Color(0x9FC0E2)],
  [0.34, new THREE.Color(0x7FA6D4)],
  [0.54, new THREE.Color(0x6E93C8)],
  [0.66, new THREE.Color(0xC96A33)],
  [0.87, new THREE.Color(0xE0642C)],
  [1.00, new THREE.Color(0xFAF1E3)]
];
const _cA = new THREE.Color(), _cB = new THREE.Color();
function ramp(t) {
  t = Math.max(0, Math.min(1, t));
  for (let i = 1; i < RAMP.length; i++) {
    if (t <= RAMP[i][0]) {
      const a = RAMP[i - 1], b = RAMP[i];
      const k = (t - a[0]) / Math.max(1e-6, b[0] - a[0]);
