/* ── cylinder wall (outward winding) ────────────────────────────────────── */
function buildWall() {
  gSil.clear(); silItems = [];
  if (!BND) { hasWall = false; return; }
  const B = BND.pts, nT = B.length, nS = 16;
  const P = [], C = [], I = [];
  let zmax = 0;
  const tops = [];
  for (let i = 0; i <= nT; i++) {
    const p = B[i % nT];
    let zt = okc(p.x, p.y); if (!Number.isFinite(zt)) zt = 0;
    zt = Math.max(zt, 0); tops.push(zt);
    if (zt > zmax) zmax = zt;
  }
  for (let i = 0; i <= nT; i++) {
    const p = B[i % nT], zt = tops[i];
    for (let j = 0; j <= nS; j++) {
      const f = j / nS;
      const w = M(p.x, p.y, zt * f);
