  // reversed winding → face normals point OUT of the tube, so the blue
  // FrontSide material is what the viewer sees from outside.
  for (let i = 0; i < nT; i++) for (let j = 0; j < nS; j++) {
    const a = i * row + j, b = (i + 1) * row + j;
    I.push(a, a + 1, b, b, a + 1, b + 1);
  }
  const geo = gridGeom(P, C, I);
  setGeom(wallF, geo);
  wallB.geometry = geo;
  hasWall = zmax > 0.02;

  // silhouette generators at the extreme-y boundary points
  let iMax = 0, iMin = 0;
  for (let i = 0; i < nT; i++) {
    if (B[i].y > B[iMax].y) iMax = i;
    if (B[i].y < B[iMin].y) iMin = i;
  }
  for (const i of [iMax, iMin]) {
