/* ── hidden-line split (near arc solid tube / far arc dashed) ───────────── */
const _camDir = new THREE.Vector3();
const _lastDir = new THREE.Vector3(9, 9, 9);
const _tmpV = new THREE.Vector3();

function arcsFor(pts, center) {
  const n = pts.length, far = new Array(n);
  for (let i = 0; i < n; i++) far[i] = _tmpV.copy(pts[i]).sub(center).dot(_camDir) > 0;
  let s = -1;
  for (let i = 0; i < n; i++) if (far[i] && !far[(i - 1 + n) % n]) { s = i; break; }
  if (s < 0) return { near: pts.slice(), far: [] };
  const farArr = [], nearArr = [];
  let i = s;
  while (far[i]) { farArr.push(pts[i]); i = (i + 1) % n; }
  const nStart = i;
  let j = nStart;
  while (!far[j]) { nearArr.push(pts[j]); j = (j + 1) % n; }
  farArr.push(pts[nStart]); nearArr.push(pts[s]);
