    new THREE.LineBasicMaterial({ color }));
}

function buildAxes() {
  const BLK = 0x000000;
  gAxes.add(dashedSeg(M(0, 0, 0), M(0, 0, 4.05), BLK));
  gAxes.add(rod(M(0, 0, 4.05), M(0, 0, 5.0), 0.013, BLK));
  gAxes.add(coneHead(M(0, 0, 5.22), new THREE.Vector3(0, 1, 0), BLK));

  gAxes.add(dashedSeg(M(0, 0, 0), M(0, 2.05, 0), BLK));
  gAxes.add(rod(M(0, 2.05, 0), M(0, 3.1, 0), 0.013, BLK));
  gAxes.add(coneHead(M(0, 3.32, 0), M(0, 1, 0).sub(M(0, 0, 0)), BLK));

  gAxes.add(dashedSeg(M(0, 0, 0), M(2.05, 0, 0), BLK));
  gAxes.add(rod(M(2.05, 0, 0), M(3.1, 0, 0), 0.013, BLK));
  gAxes.add(coneHead(M(3.32, 0, 0), M(1, 0, 0).sub(M(0, 0, 0)), BLK));

  gAxes.add(plainLine([M(2, -0.11, 0), M(2, 0.11, 0)], BLK));

  // leader arrow for the cap equation
  const a0 = M(-0.15, 3.05, 3.35), a1 = M(0.0, 1.25, 2.45);
  gAxes.add(plainLine([a0, a1], BLK));
  gAxes.add(coneHead(a1, new THREE.Vector3().subVectors(a1, a0), BLK, 0.06, 0.18));

  // curved leader arrow for the base-circle equation
  const b0 = M(2.45, -0.35, -0.95), bc = M(2.25, 0.25, -0.5), b1 = M(1.80, 0.52, 0.03);
  const bez = new THREE.QuadraticBezierCurve3(b0, bc, b1);
  gAxes.add(new THREE.Mesh(new THREE.TubeGeometry(bez, 40, 0.014, 8, false),
    new THREE.MeshBasicMaterial({ color: BLK })));
