/* ── visibility / highlight ─────────────────────────────────────────────── */
function setOpacity(mat, op) {
  mat.opacity = op;
  mat.transparent = op < 0.999;
  if (mat !== diskMat && mat !== groundMat && mat !== sliceMat) mat.depthWrite = op > 0.6;
  mat.needsUpdate = true;
}
function applyVisibility() {
  const region = viewMode === 'region';
  const onAll = hlMode === 'All';
  const xray = !region && sliceZ > 0.02 && hasSlice;

  capMesh.visible = !region && hasCap;
  groundMesh.visible = !region && hasCap;
  rimVis.visible = rimHid.visible = !region && hasCap;
  wallF.visible = wallB.visible = !region && hasWall;
  gSil.visible = !region && hasWall;
  curveMesh.visible = !region && hasCurve;
  sliceMesh.visible = sliceEdge.visible = !region && hasSlice;
  diskMesh.visible = hasDisk;
  diskRing.visible = diskHid.visible = hasDisk;

  const capOn = onAll || hlMode === 'cap';
  const wallOn = onAll || hlMode === 'wall';
  const diskOn = onAll || hlMode === 'disk' || region;
  const curveOn = onAll || hlMode === 'curve';

  const capFade = (hlMode === 'wall' || hlMode === 'curve') ? 0.35 : 1;
  setOpacity(capMat, capOn ? capFade : 0.18);
  setOpacity(groundMat, capOn ? 0.55 * capFade : 0.12);
  setOpacity(wallFMat, wallOn ? (xray ? 0.42 : 1) : 0.16);
  setOpacity(wallBMat, wallOn ? (xray ? 0.55 : 1) : 0.16);
  setOpacity(silMat, wallOn ? 1 : 0.18);
  setOpacity(silHidMat, wallOn ? 0.6 : 0.12);
  setOpacity(rimMat, capOn ? 1 : 0.25);
  setOpacity(rimHidMat, capOn ? 0.65 : 0.12);
  setOpacity(diskMat, diskOn ? (hlMode === 'disk' || region ? 0.92 : 0.8) : 0.2);
  setOpacity(diskRingMat, diskOn ? 1 : 0.22);
  setOpacity(diskHidMat, diskOn ? 0.7 : 0.15);
  setOpacity(curveMat, curveOn ? 1 : 0.28);
  curveMat.color.setHex(hlMode === 'curve' ? 0xD95F2B : 0x2F4A6B);
}

